<?php
require __DIR__.'/config.php';
$t=trim($_GET['t']??'');
$pdo=db();
$s=$pdo->prepare("SELECT q.*,b.id business_id,b.name business_name,b.type business_type,b.hero_image,l.name location_name,l.type location_type,o.name outlet_name FROM qr_codes q JOIN businesses b ON b.id=q.business_id LEFT JOIN locations l ON l.id=q.location_id LEFT JOIN outlets o ON o.id=q.outlet_id WHERE q.token=? AND q.status='active' AND b.status='active' LIMIT 1");$s->execute([$t]);$q=$s->fetch();if(!$q)exit('QR not found.');
if((isset($_GET['new'])&&$_GET['new']==='1')||empty($_SESSION['customer_token'])||($_SESSION['customer_qr_id']??0)!==$q['id']){$_SESSION['customer_token']=hash('sha256',session_id().$q['id'].random_bytes(16));$_SESSION['customer_qr_id']=(int)$q['id'];}$ct=$_SESSION['customer_token'];
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=$_POST['action']??'order';
 try{
  if($action==='service'){
   $type=trim($_POST['service_type']??'');$msg=trim($_POST['message']??'');$serviceId=(int)($_POST['service_id']??0)?:null;
   if(!$type)throw new RuntimeException('Select a service.');
   $s=$pdo->prepare("INSERT INTO service_requests(business_id,location_id,qr_id,business_service_id,type,message,status,created_at) VALUES(?,?,?,?,?,?,'new',NOW())");
   $s->execute([$q['business_id'],$q['location_id']?:null,$q['id'],$serviceId,$type,$msg]);$rid=$pdo->lastInsertId();
   $h=$pdo->prepare("INSERT INTO service_request_history(request_id,business_id,to_status,created_at) VALUES(?,?,?,NOW())");$h->execute([$rid,$q['business_id'],'new']);
   notify_business((int)$q['business_id'],'New service request','Service was requested from '.($q['location_name']??'guest location').': '.$type,null,'requests.php','requests');
   $success='Service request sent.';
  }else{
   $cart=json_decode($_POST['cart']??'[]',true);if(!is_array($cart)||!$cart)throw new RuntimeException('Your cart is empty.');
   $ids=array_map('intval',array_keys($cart));$ph=implode(',',array_fill(0,count($ids),'?'));
   $st=$pdo->prepare("SELECT i.*,c.outlet_id category_outlet_id,c.business_service_id FROM menu_items i LEFT JOIN menu_categories c ON c.id=i.category_id WHERE i.business_id=? AND i.id IN ($ph) AND i.available=1");$st->execute(array_merge([$q['business_id']],$ids));$items=$st->fetchAll();
   $total=0;$lines=[];$outletIds=[];
   foreach($items as $it){$qty=max(1,min(99,(int)($cart[$it['id']]??0)));if($qty){$line=$qty*(float)$it['price'];$total+=$line;$lines[]=[$it['id'],$it['name'],$qty,$it['price'],$line];if(!empty($it['category_outlet_id']))$outletIds[(int)$it['category_outlet_id']]=1;}}
   if(!$lines)throw new RuntimeException('No valid items.');
   $orderOutlet=count($outletIds)===1?(int)array_key_first($outletIds):($q['outlet_id']?:null);
   $pdo->beginTransaction();
   $existing=$pdo->prepare("SELECT id,order_number FROM orders WHERE business_id=? AND client_token=? LIMIT 1 FOR UPDATE");$existing->execute([$q['business_id'],$ct]);$existing=$existing->fetch();
   if($existing){$pdo->commit();$success='Order #'.$existing['order_number'].' was already received.';$successOrder=$existing['order_number'];}
   else{
    $num=date('ymdHis').strtoupper(bin2hex(random_bytes(2)));
    $ins=$pdo->prepare("INSERT INTO orders(business_id,outlet_id,location_id,qr_id,order_number,client_token,status,payment_status,payment_method,total,notes,created_at) VALUES(?,?,?,?,?,?, 'new','unpaid','till',?,?,NOW())");$ins->execute([$q['business_id'],$orderOutlet,$q['location_id']?:null,$q['id'],$num,$ct,$total,trim($_POST['notes']??'')]);$oid=(int)$pdo->lastInsertId();
    $oi=$pdo->prepare("INSERT INTO order_items(order_id,menu_item_id,item_name,qty,unit_price,line_total,created_at) VALUES(?,?,?,?,?,?,NOW())");foreach($lines as $l)$oi->execute([$oid,$l[0],$l[1],$l[2],$l[3],$l[4]]);
    $h=$pdo->prepare("INSERT INTO order_status_history(order_id,business_id,to_status,created_at) VALUES(?,?,?,NOW())");$h->execute([$oid,$q['business_id'],'new']);$pdo->commit();
    notify_business((int)$q['business_id'],'New Order #'.$num,'You have a new order from '.($q['location_name']??'customer'),null,'orders.php','orders');$success='Order #'.$num.' received.';$successOrder=$num;
   }
  }
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$err=$e->getMessage();}
}
$items=$pdo->prepare("SELECT i.*,c.name category_name,c.business_service_id,c.outlet_id category_outlet_id,s.name service_name,o.name outlet_name FROM menu_items i LEFT JOIN menu_categories c ON c.id=i.category_id LEFT JOIN business_services s ON s.id=c.business_service_id LEFT JOIN outlets o ON o.id=c.outlet_id WHERE i.business_id=? AND i.available=1 ORDER BY c.sort_order,c.id,i.sort_order,i.id");$items->execute([$q['business_id']]);$items=$items->fetchAll();
$cats=[];foreach($items as $i){$key=$i['business_service_id']?:0;$cats[$key][$i['category_name']??'Menu'][]=$i;}
$services=[];$ss=$pdo->prepare("SELECT id,name,icon FROM business_services WHERE business_id=? AND enabled=1 ORDER BY id");$ss->execute([$q['business_id']]);foreach($ss->fetchAll() as $x)$services[]=$x;
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#1E5A6B"><title><?=e($q['business_name'])?> · SERV</title><script>(function(){try{var t=localStorage.getItem("serv_theme");if(t!=="dark"&&t!=="light")t="light";document.documentElement.dataset.theme=t;document.documentElement.style.colorScheme=t;}catch(e){document.documentElement.dataset.theme="light";}})();</script><link rel="stylesheet" href="assets/css/app.css?v=2.3.3"></head><body><div class="customer-app"><header class="customer-head<?=!empty($q['hero_image'])?' has-hero':''?>"<?=!empty($q['hero_image'])?' style="--hero-image:url(\''.e($q['hero_image']).'\')"':''?>><div class="customer-head-top"><div class="brand">SERV</div><button type="button" class="header-theme" onclick="SERVTheme.toggle()" aria-label="Switch theme"><span id="theme-icon">☾</span><b id="theme-label">Light</b></button></div><div class="eyebrow"><?=e($q['business_name'])?></div><h1><?=e($q['business_type']==='hotel'?'Welcome, Guest':'Welcome')?></h1><p><?=e($q['location_name']??'')?></p></header><main class="customer-body">
<?php if(isset($success)):?><div class="alert success"><?=e($success)?><?php if(isset($successOrder)):?><div style="margin-top:10px"><a class="btn gold" href="customer.php?t=<?=rawurlencode($t)?>&new=1">Start new order</a></div><?php endif;?></div><?php endif;?><?php if(isset($err)):?><div class="alert error"><?=e($err)?></div><?php endif;?>
<?php if($q['business_type']==='hotel'):?>
<section><h2>Hotel services</h2><p class="small muted">Choose a service below. Menus are shown only for the service you select.</p><div class="service-grid"><?php foreach($services as $sv):?><button type="button" class="service-tile" data-service-id="<?=$sv['id']?>" data-service-name="<?=e($sv['name'])?>"><span><?=e($sv['icon'])?></span><b><?=e($sv['name'])?></b></button><?php endforeach;?></div></section>
<section id="servicePanel" class="panel hidden"><div class="section-head"><h3 id="serviceTitle" style="margin:0">Service</h3><button type="button" class="btn" id="closeService">Close</button></div><div id="serviceMenu"></div><div id="serviceRequest" class="hidden" style="margin-top:12px"><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="service"><input type="hidden" name="service_id" id="serviceId"><input type="hidden" name="service_type" id="serviceType"><textarea name="message" placeholder="Tell us what you need..."></textarea><button class="btn gold" style="width:100%;margin-top:10px">Send request</button></form></div></section>
<?php endif;?>
<?php if($q['business_type']==='restaurant'):?><section><div class="section-head"><h2>Menu</h2></div><?php foreach(($cats[0]??[]) as $cat=>$list):?><h3><?=e($cat)?></h3><?php foreach($list as $i):?><div class="food"><div><b><?=e($i['name'])?></b><div class="small muted"><?=e($i['description'])?></div><strong><?=money((float)$i['price'])?></strong></div><button type="button" onclick="add(<?=$i['id']?>)">+ Add</button></div><?php endforeach;endforeach;?></section><?php endif;?>
<?php if($q['business_type']==='restaurant' || $q['business_type']==='hotel'):?><section id="cartSection"><div id="cartBox" class="panel" style="margin-top:12px"><div class="section-head"><h3 style="margin:0">Your cart</h3><span id="cartCount" class="badge">0 items</span></div><div id="cartItems" class="small muted" style="margin-top:10px">Your cart is empty.</div></div><form method="post" id="orderForm"><?=csrf_field()?><input type="hidden" name="action" value="order"><input type="hidden" name="cart" id="cart"><input name="notes" placeholder="Special instructions (optional)"><button class="btn primary sticky-order" type="button" onclick="submitOrder()">Place order · <span id="total">₦0.00</span></button></form></section><?php endif;?>
<?php if(isset($successOrder)):?><section class="panel" id="tracking"><h3>Track order #<?=e($successOrder)?></h3><p class="small muted">Your order status will appear here.</p></section><?php endif;?>
</main></div>
<script src="assets/js/serv.js"></script><script>
const prices={<?php foreach($items as $i):?><?=$i['id']?>:<?=json_encode((float)$i['price'])?>,<?php endforeach;?>};
const names={<?php foreach($items as $i):?><?=$i['id']?>:<?=json_encode($i['name'])?>,<?php endforeach;?>};
const itemServices={<?php foreach($items as $i):?><?=$i['id']?>:<?=json_encode((int)($i['business_service_id']??0))?>,<?php endforeach;?>};
const itemData={<?php foreach($items as $i):?><?=$i['id']?>:{service:<?=json_encode((int)($i['business_service_id']??0))?>,category:<?=json_encode($i['category_name']??'Menu')?>,outlet:<?=json_encode($i['outlet_name']??'')?>,description:<?=json_encode($i['description']??'')?>},<?php endforeach;?>};
const serviceMenus=<?=json_encode($cats,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;const cart={};
function add(id){cart[id]=(cart[id]||0)+1;render()}
function removeItem(id){if(!cart[id])return;cart[id]--;if(cart[id]<=0)delete cart[id];render()}
function render(){let t=0,count=0,html='';for(const id in cart){const qty=cart[id];count+=qty;t+=qty*prices[id];html+=`<div class="row" style="padding:10px 0"><div><b>${escapeHtml(names[id])}</b><div class="small muted">₦${(prices[id]*qty).toLocaleString('en-NG',{minimumFractionDigits:2})} · ${qty} ×</div></div><div style="display:flex;gap:6px;align-items:center"><button type="button" class="btn" onclick="removeItem(${id})">−</button><b>${qty}</b><button type="button" class="btn" onclick="add(${id})">+</button></div></div>`}const ci=document.getElementById('cartItems');if(ci)ci.innerHTML=html||'Your cart is empty.';const cc=document.getElementById('cartCount');if(cc)cc.textContent=count+' item'+(count===1?'':'s');const total=document.getElementById('total');if(total)total.textContent='₦'+t.toLocaleString('en-NG',{minimumFractionDigits:2});const hidden=document.getElementById('cart');if(hidden)hidden.value=JSON.stringify(cart)}
function escapeHtml(v){return String(v).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function submitOrder(){if(!Object.keys(cart).length){alert('Add an item first.');return}const b=document.querySelector('.sticky-order');if(b?.dataset.submitting==='1')return;if(b){b.dataset.submitting='1';b.disabled=true;b.textContent='Sending order…'}document.getElementById('orderForm').submit()}
function openService(id,name){const panel=document.getElementById('servicePanel'),title=document.getElementById('serviceTitle'),menu=document.getElementById('serviceMenu'),req=document.getElementById('serviceRequest');if(!panel)return;title.textContent=name;document.getElementById('serviceId').value=id;document.getElementById('serviceType').value=name;menu.innerHTML='';req.classList.add('hidden');let groups=serviceMenus[String(id)]||{};let has=false;Object.entries(groups).forEach(([cat,list])=>{has=true;const h=document.createElement('h3');h.textContent=cat;menu.appendChild(h);list.forEach(i=>{const row=document.createElement('div');row.className='food';row.innerHTML=`<div><b>${escapeHtml(i.name)}</b><div class="small muted">${escapeHtml(i.description||'')}</div><strong>₦${Number(i.price).toLocaleString('en-NG',{minimumFractionDigits:2})}</strong></div><button type="button" onclick="add(${i.id})">+ Add</button>`;menu.appendChild(row)})});if(!has){req.classList.remove('hidden');menu.innerHTML='<p class="small muted">No orderable items have been added for this service yet. You can send a request instead.</p>'}panel.classList.remove('hidden');panel.scrollIntoView({behavior:'smooth',block:'start'})}
document.querySelectorAll('.service-tile').forEach(btn=>btn.addEventListener('click',()=>openService(Number(btn.dataset.serviceId),btn.dataset.serviceName)));document.getElementById('closeService')?.addEventListener('click',()=>document.getElementById('servicePanel').classList.add('hidden'));render();
<?php if(isset($successOrder)):?>const orderNo=<?=json_encode($successOrder)?>,qrToken=<?=json_encode($t)?>;let lastStatus='new';async function track(){try{const r=await fetch('api/order-status.php?t='+encodeURIComponent(qrToken)+'&order='+encodeURIComponent(orderNo),{cache:'no-store'});const d=await r.json();if(!d.ok)return;const o=d.order;const labels={new:'Order received',accepted:'Order accepted',preparing:'Preparing your order',ready:'Order ready',serving:'On the way',served:'Served',completed:'Completed',cancelled:'Cancelled'};const orderSteps=['new','accepted','preparing','ready','serving','served','completed'];const idx=orderSteps.indexOf(o.status);document.getElementById('tracking').innerHTML='<h3>Order #'+escapeHtml(o.order_number)+'</h3><div class="timeline">'+orderSteps.map((k,i)=>'<div class="step '+(i<idx?'done ':i===idx?'current ':'')+'">'+labels[k]+'</div>').join('')+'</div>';if(o.status!==lastStatus&&lastStatus!=='new'&&'Notification'in window&&Notification.permission==='granted'){try{new Notification('SERV · '+labels[o.status],{body:'Order #'+o.order_number+' · '+labels[o.status],icon:'assets/icon.svg'})}catch(e){}}lastStatus=o.status}catch(e){}}track();setInterval(track,5000);<?php endif;?>
</script><script>window.SERVTheme=(function(){function sync(t){t=t==='dark'?'dark':'light';document.documentElement.dataset.theme=t;document.documentElement.style.colorScheme=t;document.body.classList.toggle('dark',t==='dark');document.body.classList.toggle('light',t==='light');try{localStorage.setItem('serv_theme',t);}catch(e){}var icon=document.getElementById('theme-icon'),label=document.getElementById('theme-label');if(icon)icon.textContent=t==='dark'?'☀':'☾';if(label)label.textContent=t==='dark'?'Dark':'Light';}return{apply:sync,toggle:function(){sync(document.documentElement.dataset.theme==='dark'?'light':'dark')}}})();SERVTheme.apply(document.documentElement.dataset.theme||'light');</script></body></html>
